      "given": "$C_6H_5Cl$ (chlorobenzene) + $CH_3Cl$ (chloromethane) + $2Na$ in dry ether.",
      "formula": "$Ar-X + 2Na + R-X \\xrightarrow{\\text{dry ether}} Ar-R + 2NaX$",
